const inner = { x0: SAFE_L, y0: SAFE_T, x1: W - SAFE_R, y1: H - SAFE_B };
ctx.rect(0, 0, W, H); ctx.rect(inner.x0, inner.y0, inner.x1 - inner.x0, inner.y1 - inner.y0);
ctx.fill('evenodd');   // 바깥만 어둡게

function intrusion(r, s) {                       // 요소 r 이 값 s 의 여백을 넘은 px
  const v = [];
  if (s.b != null) v.push(r.y1 - (H - s.b));
  return Math.max(0, ...v);
}
